import { test } from 'node:test';
import assert from 'node:assert/strict';
import { analisarStackTrace, funcaoQueLancou } from './solution.mjs';

test('analisarStackTrace extrai os frames, sem a mensagem e sem o ruído interno', () => {
  const stack = `Error: divisão por zero
    at dividir (server.mjs:12:9)
    at rota (rotas.mjs:45:3)
    at processTicksAndRejections (node:internal/process/task_queues:96:5)`;
  assert.deepEqual(analisarStackTrace(stack), [
    { funcao: 'dividir', arquivo: 'server.mjs', linha: 12 },
    { funcao: 'rota', arquivo: 'rotas.mjs', linha: 45 }
  ]);
});

test('analisarStackTrace devolve lista vazia para texto sem frames ou não-texto', () => {
  assert.deepEqual(analisarStackTrace('só uma mensagem, sem frames'), []);
  assert.deepEqual(analisarStackTrace(''), []);
  assert.deepEqual(analisarStackTrace(42), []);
});

test('funcaoQueLancou devolve a função de onde o erro saiu', () => {
  const erro = new Error('algo quebrou');
  erro.stack = `Error: algo quebrou
    at calcular (server.mjs:12:9)
    at pedido (server.mjs:30:5)`;
  assert.equal(funcaoQueLancou(erro), 'calcular');
});

test('funcaoQueLancou devolve desconhecida quando não há stack', () => {
  assert.equal(funcaoQueLancou({ mensagem: 'sem stack' }), 'desconhecida');
});

solutionCode:
export function analisarStackTrace(stackTrace) {
  if (typeof stackTrace !== 'string' || stackTrace.trim() === '') return [];
  const frames = [];
  for (const linha of stackTrace.split('\n')) {
    const m = /at (.+?) \(([^:]+):(\d+):(\d+)\)/.exec(linha.trim());
    if (!m) continue;                            // linha de mensagem ou ruído
    const arquivo = m[2];
    if (arquivo.startsWith('node:')) continue;   // frames internos do Node: ignorar
    frames.push({ funcao: m[1], arquivo, linha: Number(m[3]) });
  }
  return frames;
}

export function funcaoQueLancou(erro) {
  if (!erro || typeof erro.stack !== 'string') return 'desconhecida';
  const frames = analisarStackTrace(erro.stack);
  return frames.length > 0 ? frames[0].funcao : 'desconhecida';
}
